package com.nexusdrive.auth.service;import com.nexusdrive.common.exception.ValidationException;import java.time.*;import java.util.concurrent.*;import org.springframework.stereotype.Component;@Component public class LoginRateLimiter {private record Window(long started,int count){}private final ConcurrentMap<String,Window> map=new ConcurrentHashMap<>();public void check(String key){long now=Instant.now().getEpochSecond();map.compute(key,(k,w)->{if(w==null||now-w.started>=60)return new Window(now,1);if(w.count>=20)throw new ValidationException("Too many login attempts; retry later");return new Window(w.started,w.count+1);});}}
